package org.jsoup.nodes;

import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import java.util.Map;
import org.jsoup.SerializationException;
import org.jsoup.helper.Validate;
import org.jsoup.internal.StringUtil;
import org.jsoup.nodes.Attribute;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

public class Attribute_getValue_TriageGen0Test {
    @Test
    public void testGetValueWithKeyAndVal() {
        Attribute attribute = new Attribute("testKey", "testValue");
        assertEquals("testValue", attribute.getValue());
    }

    @Test
    public void testGetValueWithKeyAndParent() {
        Attributes parent = new Attributes();
        Attribute attribute = new Attribute("testKey", "testValue", parent);
        assertEquals("testValue", attribute.getValue());
    }

    @Test
    public void testGetValueWithoutKeyAndVal() {
        Attribute attribute = new Attribute();
        assertNull(attribute.getValue());
    }

    @Test
    public void testGetValueWithNullKeyAndVal() {
        Attribute attribute = new Attribute(null, null);
        assertNull(attribute.getValue());
    }

    @Test
    public void testGetValueWithEmptyKeyAndVal() {
        Attribute attribute = new Attribute("", "");
        assertEquals("", attribute.getValue());
    }
}
